// Builds ../app/vendor/editor.js from entry.js.
//
//   cd vendor && npm ci && npm run build
//
// The output is committed: Yard deploys the app directory as it is, and the
// app itself has no build step. Rebuild only to change what entry.js exports
// or to upgrade a pinned version in package.json.

import { build } from "esbuild";
import { statSync } from "node:fs";

const OUT = "../app/vendor/editor.js";

const result = await build({
  entryPoints: ["entry.js"],
  bundle: true,
  format: "esm",
  target: "es2022",
  minify: true,
  legalComments: "eof",
  metafile: true,
  outfile: OUT,
  banner: {
    js: "// GENERATED by vendor/build.mjs from vendor/entry.js. Do not edit; rebuild instead.",
  },
});

// Every package here must be bundled exactly once. A second copy of yjs or
// prosemirror-model builds fine and then fails at runtime, so fail now.
const SINGLE = [
  "yjs",
  "lib0",
  "y-protocols",
  "prosemirror-model",
  "prosemirror-state",
  "prosemirror-view",
  "prosemirror-transform",
  "@tiptap/core",
  "@tiptap/y-tiptap",
];
const roots = new Map();
for (const input of Object.keys(result.metafile.inputs)) {
  const match = input.match(/^(.*node_modules\/)((?:@[^/]+\/)?[^/]+)\//);
  if (!match || !SINGLE.includes(match[2])) continue;
  const set = roots.get(match[2]) || new Set();
  set.add(match[1]);
  roots.set(match[2], set);
}
for (const [name, dirs] of roots) {
  if (dirs.size > 1) {
    console.error(`duplicate copies of ${name}:\n  ${[...dirs].join("\n  ")}`);
    process.exit(1);
  }
}

const kb = (statSync(OUT).size / 1024).toFixed(0);
console.log(`wrote ${OUT} (${kb} KB)`);
